import {
  Body,
  Controller,
  Get,
  InternalServerErrorException,
  NotFoundException,
  Param,
  Post,
  Res,
  UseFilters,
} from '@nestjs/common';
import {
  ApiBody,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
} from '@nestjs/swagger';
import { Response } from 'express';
import { CustomerService } from './customer.service';
import { CustomerCodesDTO } from './dtos/customer-codes.dto';
import { CustomerParameterDTO } from './dtos/customer-parameter.dto';
import { CustomerResponseDTO } from './dtos/customer-response.dto';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';

// Controller for handling customer-related requests
@Controller('customer')
export class CustomerController {
  public constructor(private readonly customerService: CustomerService) {}

  @ApiOperation({
    description:
      'This endpoint allows you to retrieve the details of a customer based on a specific customer code.',
    summary: 'Get details of customer by customer code',
  })
  @ApiOkResponse({
    description: 'The customer details',
    type: CustomerResponseDTO,
  })
  @ApiParam({
    example: 'C1',
    name: 'customerCode',
    required: true,
    type: String,
  })
  @Get('/getCustomerByCode/:customerCode')
  public async getCustomerByCode(
    @Param() parameters: CustomerParameterDTO,
  ): Promise<CustomerResponseDTO> {
    try {
      const customer = await this.customerService.getCustomerByCode(
        parameters.customerCode,
      );
      return customer;
    } catch (error) {
      throw new NotFoundException(error.message);
    }
  }

  @ApiOperation({
    description:
      'Retrieve details of multiple customers based on a list of customer codes provided in the request body.',
    summary: 'Get details of multiple customers by customer codes',
  })
  @ApiOkResponse({
    description: 'Details of the requested customers',
    type: [CustomerResponseDTO],
  })
  @ApiBody({
    description: 'List of customer codes to retrieve details for',
    type: CustomerCodesDTO,
  })
  @Post('/getCustomersByCodes')
  public async getCustomersByCodes(
    @Body()
    customerParameters: {
      customerCodes: Array<string>;
      sapServer: string;
    },
  ): Promise<Array<CustomerResponseDTO>> {
    try {
      const { sapServer, customerCodes } = customerParameters;
      // Retrieve customers based on the array of codes
      const customers = await this.customerService.getCustomersByCodes(
        customerCodes,
        sapServer,
      );

      return customers;
    } catch (error) {
      const errorNotFoundException =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'An error occurred while fetching customer details',
              error,
            );
      throw errorNotFoundException;
    }
  }

  @ApiOperation({
    description:
      'Retrieve details of multiple customers based on a list of customer codes provided in the request body.',
    summary: 'Get details of multiple customers by customer codes',
  })
  @ApiOkResponse({
    description: 'Details of the requested customers',
    schema: {
      type: 'object',
      additionalProperties: { type: 'string' }, // The response is an object represent Record<string,string>
    },
  })
  @ApiBody({
    description: 'List of customer codes to retrieve details for',
    type: Array<string>,
  })
  @UseFilters(MesGenericErrorFilter)
  @Post('/getCustomersByCodesList')
  public async getCustomersByCodesList(
    @Body()
    customerParameters: { sapServer: string; customerCodes: Array<string> },
    @Res() response: Response,
  ): Promise<Response> {
    const { sapServer, customerCodes } = customerParameters;

    // Call service to retrieve customers
    const customers = await this.customerService.getCustomerDescByCustomerCodes(
      sapServer,
      customerCodes,
    );

    return response.json(customers);
  }
}

