@ApiTags('Data Ingestion')
@Controller('data-ingestion')
export class IngestionEventTrackingController {
  private readonly logger = new AppLogger(
    IngestionEventTrackingController.name,
  );

  public constructor(
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
  ) {}

  @Delete('deleteExpiredIngestionEventTracking')
  @ApiOperation({
    description:
      'Deletes Ingestion Event Tracking  that are older than the defined retention time (1 day after launchDatetime).',
    summary: 'Delete expired Ingestion Event Tracking records',
  })
